const named=(parent,name,type)=>{const found=parent.children.filter(n=>n.name===name);if(found.length>1)throw Error('Duplicate existing node: '+name);if(found[0]&&found[0].type!==type)throw Error('Existing node type conflict: '+name);return found[0]||null;};
