const styles=new Map();
for(const s of specs){const actual=await figma.getStyleByIdAsync(s.styleId);if(!actual||actual.type!=='TEXT'||actual.name!==s.name||actual.description!==s.description||!sameRecipe(actual,s))throw Error('TextStyle preflight mismatch: '+s.id);styles.set(s.id,actual);await load(actual.fontName);}
