const vars=new Map();
for(const [name,id,type,scope]of TOKENS){const v=await figma.variables.getVariableByIdAsync(id);if(!v||v.name!==name||v.resolvedType!==type||v.variableCollectionId!==collection.id||!v.scopes.includes(scope))throw Error('Variable preflight mismatch: '+name);vars.set(name,v);}
