  await text(card,'Valores',`Manrope ${s.fontStyle} · Peso ${s.weight} · ${s.fontSize} px · Interlínea ${fmtUnit(s.lineHeight)} · Tracking ${fmtUnit(s.letterSpacing)}\n${s.id}`,'body-regular',width,'color/text/secondary');
  await text(card,'Descripción',s.description,'body-regular',width);
